<?php
$n = trim(fgets(STDIN));
$s = trim(fgets(STDIN));

$count = 0;

for ($c = ord('z'); $c >= ord('b'); $c--) {
    do {
        $changed = false;
        $len = strlen($s);
        for ($i = 0; $i < $len; $i++) {
            if (ord($s[$i]) == $c) {
                $prevMatch = ($i > 0 && ord($s[$i-1]) == $c - 1);
                $nextMatch = ($i < $len - 1 && ord($s[$i+1]) == $c - 1);
                if ($prevMatch || $nextMatch) {
                    $s = substr($s, 0, $i) . substr($s, $i+1);
                    $count++;
                    $changed = true;
                    break;
                }
            }
        }
    } while ($changed);
}

echo $count . "\n";
?>
